select id, position, role, reports_to, tier, plain_role_explanation, budget_micros, spent_micros, paused from jsonb_populate_recordset(null::public.agents, $j$[{"id":"agent-arch-01","position":1,"role":"Chief Systems Architect (CEO / CTO)","reports_to":"Human Board (Ring-0 Sanction Gate)","tier":"FRONTIER (Claude Opus / Gemini Pro)","plain_role_explanation":"Decomposes high-level user goals into Goal-Ancestry trees, reviews Typed Evidence Receipts, and arbitrates cross-agent AST merges.","budget_micros":50000000,"spent_micros":14200000,"paused":false},{"id":"agent-rust-02","position":2,"role":"Principal Rust Kernel Engineer","reports_to":"agent-arch-01","tier":"FRONTIER (ACP v3.2.0 Conductor)","plain_role_explanation":"Implements core Rust traits in isolated jj-lib workspaces under the Asymmetric 3-Class Dual Barrier.","budget_micros":35000000,"spent_micros":18900000,"paused":false},{"id":"agent-junie-lite-03","position":3,"role":"ForgeLite Worktree Scaffolder","reports_to":"agent-rust-02","tier":"FORGE_LITE_WORKHORSE (Qwen 3.6 27B / Local Qwen3.5)","plain_role_explanation":"Handles mechanical edits, test scaffolding, changelog updates, and lint fixes at $0/free workhorse cost so you never ration experiments.","budget_micros":10000000,"spent_micros":1200000,"paused":false},{"id":"agent-sec-qa-04","position":4,"role":"Adversarial Red-Team & QA Verifier","reports_to":"agent-arch-01","tier":"FRONTIER + OpenCodeReview v1.13.0","plain_role_explanation":"Runs deterministic diff reviews (with deleted-file line anchoring) and CI-GATE-S1 to S4 fault injection before any task reaches 100% confidence.","budget_micros":25000000,"spent_micros":23500000,"paused":false}]$j$::jsonb);
